No existing codebase found. Here's how to debounce a search input:

**React (most common):**
```jsx
import { useState, useEffect } from 'react';

function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (query.trim()) {
        // API call here
        fetch(`/api/search?q=${query}`)
          .then(res => res.json())
          .then(data => setResults(data));
      }
    }, 300); // 300ms delay

    return () => clearTimeout(timer); // cleanup
  }, [query]);

  return (
    <div>
      <input 
        type="text" 
        value={query} 
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      {results.map(item => <div key={item.id}>{item.name}</div>)}
    </div>
  );
}
```

**Vanilla JS with reusable debounce utility:**
```javascript
function debounce(func, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func(...args), delay);
  };
}

const searchInput = document.getElementById('search');
const performSearch = debounce((query) => {
  fetch(`/api/search?q=${query}`)
    .then(res => res.json())
    .then(data => console.log(data));
}, 300);

searchInput.addEventListener('input', (e) => {
  performSearch(e.target.value);
});
```

Key points: timeout clears on each keystroke, only the final one triggers API after 300ms silence. Adjust delay as needed (150-500ms typical).
